package fetchall

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"sync"
)

// Result holds one successful output from Process, indexed by its position
// in the input slice.
type Result struct {
	Index  int
	Output string
}

// Process runs operation concurrently on every input, with at most concurrency
// operations in flight at any moment.
//
// concurrency must be >= 1. Empty inputs returns (nil, nil).
// When one or more operations fail, every individual failure remains reachable
// in the returned aggregated error via errors.Is / errors.AsType / errors.As.
// Results are returned ordered by Index ascending.
func Process(
	ctx context.Context,
	inputs []string,
	concurrency int,
	operation func(ctx context.Context, input string) (string, error),
) ([]Result, error) {
	if concurrency < 1 {
		return nil, fmt.Errorf("fetchall: concurrency must be at least 1, got %d", concurrency)
	}
	if len(inputs) == 0 {
		return nil, nil
	}

	// Buffered channel acts as a counting semaphore: send to acquire, receive
	// to release, so at most concurrency goroutines are in-flight.
	sem := make(chan struct{}, concurrency)

	var (
		mu      sync.Mutex
		results []Result
		errs    []error
	)
	var wg sync.WaitGroup

	for i, input := range inputs {
		// Wait for a semaphore slot, but abort launching new work if the
		// parent context is cancelled.
		select {
		case sem <- struct{}{}:
		case <-ctx.Done():
			goto wait
		}

		idx, inp := i, input
		wg.Add(1) //nolint:staticcheck // WaitGroup.Go not used because semaphore lifecycle straddles goroutine boundaries
		go func() {
			defer func() {
				<-sem // release the semaphore slot
				wg.Done()
			}()
			out, err := operation(ctx, inp)
			mu.Lock()
			if err != nil {
				errs = append(errs, fmt.Errorf("input %d: %w", idx, err))
			} else {
				results = append(results, Result{Index: idx, Output: out})
			}
			mu.Unlock()
		}()
	}
wait:
	wg.Wait()

	// Sort results by Index to match input order.
	sort.Slice(results, func(a, b int) bool {
		return results[a].Index < results[b].Index
	})

	if len(errs) > 0 {
		return results, errors.Join(errs...)
	}
	return results, nil
}

package fetchall

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"testing"
	"time"
)

var errSentinel = errors.New("sentinel failure")

// --- Edge cases ---

func TestProcess_EmptyInputs(t *testing.T) {
	results, err := Process(context.Background(), nil, 1, nil)
	if results != nil || err != nil {
		t.Fatalf("nil inputs: got (%v, %v), want (nil, nil)", results, err)
	}

	results, err = Process(context.Background(), []string{}, 1, nil)
	if results != nil || err != nil {
		t.Fatalf("empty inputs: got (%v, %v), want (nil, nil)", results, err)
	}
}

func TestProcess_ConcurrencyUnderOne(t *testing.T) {
	_, err := Process(context.Background(), []string{"a"}, 0, nil)
	if err == nil {
		t.Fatal("concurrency=0: expected error, got nil")
	}

	_, err = Process(context.Background(), []string{"a"}, -5, nil)
	if err == nil {
		t.Fatal("concurrency=-5: expected error, got nil")
	}
}

// --- Success paths ---

func TestProcess_AllSucceed(t *testing.T) {
	inputs := []string{"a", "b", "c", "d"}
	op := func(_ context.Context, s string) (string, error) {
		return s + s, nil
	}
	results, err := Process(context.Background(), inputs, 2, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != len(inputs) {
		t.Fatalf("got %d results, want %d", len(results), len(inputs))
	}
	for i, r := range results {
		if r.Index != i {
			t.Errorf("result[%d].Index = %d, want %d", i, r.Index, i)
		}
		if r.Output != inputs[i]+inputs[i] {
			t.Errorf("result[%d].Output = %q, want %q", i, r.Output, inputs[i]+inputs[i])
		}
	}
}

func TestProcess_ResultsOrderedByIndex(t *testing.T) {
	// Even though operations complete out of order (we delay the first input),
	// results must be returned ordered by Index.
	inputs := []string{"slow", "fast", "fast2"}
	block := make(chan struct{})
	op := func(ctx context.Context, s string) (string, error) {
		if s == "slow" {
			<-ctx.Done()
			return "", ctx.Err()
		}
		_ = block
		return s, nil
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // cancel so "slow" returns immediately

	results, err := Process(ctx, inputs, 2, op)
	if err == nil {
		t.Fatal("expected error from cancelled context")
	}
	// fast and fast2 should succeed; Index should be 1,2 not out of order.
	if len(results) != 2 {
		t.Fatalf("got %d results, want 2", len(results))
	}
	if results[0].Index != 1 {
		t.Errorf("results[0].Index = %d, want 1", results[0].Index)
	}
	if results[1].Index != 2 {
		t.Errorf("results[1].Index = %d, want 2", results[1].Index)
	}
}

// --- Failure paths ---

func TestProcess_SomeFail(t *testing.T) {
	inputs := []string{"ok", "fail1", "ok2", "fail2"}
	op := func(_ context.Context, s string) (string, error) {
		if s == "fail1" || s == "fail2" {
			return "", errSentinel
		}
		return s, nil
	}
	results, err := Process(context.Background(), inputs, 2, op)
	if err == nil {
		t.Fatal("expected aggregated error, got nil")
	}
	if len(results) != 2 {
		t.Fatalf("got %d results, want 2", len(results))
	}
	if results[0].Index != 0 || results[0].Output != "ok" {
		t.Errorf("results[0] = %+v, want {Index:0 Output:ok}", results[0])
	}
	if results[1].Index != 2 || results[1].Output != "ok2" {
		t.Errorf("results[1] = %+v, want {Index:2 Output:ok2}", results[1])
	}
	// Each individual failure must be reachable via errors.Is / errors.AsType.
	if !errors.Is(err, errSentinel) {
		t.Error("aggregated error does not wrap errSentinel")
	}
	if !errors.Is(err, fmt.Errorf("input 1: %w", errSentinel)) {
		t.Error("aggregated error does not wrap input-1 failure")
	}
	// Verify count of wrapped sentinels using Go 1.26 AsType.
	var all []*failureMarker
	for {
		f, ok := errors.AsType[*failureMarker](err)
		if !ok {
			break
		}
		all = append(all, f)
		err = f.Unwrap()
	}
	if len(all) != 2 {
		t.Fatalf("found %d sentinel errors in tree, want 2", len(all))
	}
}

type failureMarker struct {
	msg string
	next error
}

func (f *failureMarker) Error() string { return f.msg }
func (f *failureMarker) Unwrap() error { return f.next }

// Test that concrete typed errors are also reachable.
type typedError struct{ msg string }

func (e *typedError) Error() string { return e.msg }

func TestProcess_FailuresReachableViaAsType(t *testing.T) {
	inputs := []string{"a", "b"}
	op := func(_ context.Context, s string) (string, error) {
		return "", &typedError{msg: s}
	}
	_, err := Process(context.Background(), inputs, 1, op)
	if err == nil {
		t.Fatal("expected error")
	}
	// Both typed errors must be reachable.
	var found int
	base := err
	for {
		te, ok := errors.AsType[*typedError](base)
		if !ok {
			break
		}
		found++
		base = errors.Unwrap(base)
	}
	if found != 2 {
		t.Fatalf("found %d typedError instances, want 2", found)
	}
}

func TestProcess_AllFail(t *testing.T) {
	inputs := []string{"a", "b", "c"}
	op := func(_ context.Context, s string) (string, error) {
		return "", fmt.Errorf("fail %s", s)
	}
	results, err := Process(context.Background(), inputs, 2, op)
	if err == nil {
		t.Fatal("expected aggregated error")
	}
	if results != nil {
		t.Fatalf("expected nil results, got %v", results)
	}
}

// --- Concurrency enforcement ---

func TestProcess_ConcurrencyLimitRespected(t *testing.T) {
	const concurrency = 3
	var mu sync.Mutex
	var inflight int
	var peak int

	inputs := make([]string, 10)
	for i := range inputs {
		inputs[i] = fmt.Sprintf("%d", i)
	}

	op := func(ctx context.Context, s string) (string, error) {
		mu.Lock()
		inflight++
		if inflight > peak {
			peak = inflight
		}
		mu.Unlock()

		// Block so we can observe concurrency.
		select {
		case <-ctx.Done():
			return "", ctx.Err()
		case <-time.After(5 * time.Millisecond):
		}

		mu.Lock()
		inflight--
		mu.Unlock()

		return s, nil
	}

	_, err := Process(context.Background(), inputs, concurrency, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if peak > concurrency {
		t.Fatalf("peak concurrency = %d, want ≤ %d", peak, concurrency)
	}
}

// --- Context propagation ---

func TestProcess_ContextCancellation(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // already cancelled

	results, err := Process(ctx, []string{"a", "b"}, 2,
		func(ctx context.Context, s string) (string, error) {
			return s, nil
		})
	if err == nil {
		t.Fatal("expected error from cancelled context, got nil")
	}
	if !errors.Is(err, context.Canceled) {
		t.Errorf("error does not wrap context.Canceled: %v", err)
	}
	_ = results // may be nil or partial; spec doesn't mandate which
}

func TestProcess_ParentContextPassed(t *testing.T) {
	type ctxKey struct{}
	ctx := context.WithValue(context.Background(), ctxKey{}, "value")
	inputs := []string{"a"}
	var seenCtx context.Context
	op := func(ctx context.Context, s string) (string, error) {
		seenCtx = ctx
		return s, nil
	}
	_, err := Process(ctx, inputs, 1, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if v := seenCtx.Value(ctxKey{}); v != "value" {
		t.Fatalf("parent context value not propagated: got %v, want %q", v, "value")
	}
}

